def executar_seed():
    """Insere as questoes de 2023 que ainda nao estao no banco."""
    engine = create_engine(DATABASE_URL)
    Base.metadata.create_all(engine)
    Session = sessionmaker(bind=engine)
    session = Session()

    inseridas = 0
    ignoradas = 0
    for dados in QUESTOES_2023:
        existe = (
            session.query(Questao)
            .filter_by(ano=dados["ano"], numero=dados["numero"])
            .first()
        )
        if existe:
            ignoradas += 1
            continue
        session.add(Questao(**dados))
        inseridas += 1

    session.commit()
    print(
        f"Seed 2023 concluido: {inseridas} questoes inseridas, {ignoradas} ja existiam."
    )
    session.close()


if __name__ == "__main__":
    executar_seed()
